	int bezFraction = (int)(1.0/downRez);
	double bezTrim = (double)bezFraction/(bezFraction+1.0);
	downRez = 0.99999999 / bezFraction;
	bezTrim = 1.0-(downRez*bezTrim);
	
    const float aw_f_reg4n = (float)reg4n;
