			if (c4AL > d4A) c4AL = 0;
			if (c4BL > d4B) c4BL = 0;
			if (c4CL > d4C) c4CL = 0;
			if (c4DL > d4D) c4DL = 0;
			if (c4DR > d4D) c4DR = 0;
			if (c4HR > d4H) c4HR = 0;
			if (c4LR > d4L) c4LR = 0;
			if (c4PR > d4P) c4PR = 0;
			hAL = a4AL[c4AL]; hBL = a4BL[c4BL]; hCL = a4CL[c4CL]; hDL = a4DL[c4DL];
			hAR = a4DR[c4DR]; hBR = a4HR[c4HR]; hCR = a4LR[c4LR]; hDR = a4PR[c4PR];
			hEL = -(hAL + hBL + hCL + hDL);
			hER = -(hAR + hBR + hCR + hDR);
			a4EL[c4EL] = hAL*2.0f + hEL;
			a4FL[c4FL] = hBL*2.0f + hEL;
			a4GL[c4GL] = hCL*2.0f + hEL;
			a4HL[c4HL] = hDL*2.0f + hEL;
			a4CR[c4CR] = hAR*2.0f + hER;
			a4GR[c4GR] = hBR*2.0f + hER;
			a4KR[c4KR] = hCR*2.0f + hER;
			a4OR[c4OR] = hDR*2.0f + hER;
			c4EL++; c4FL++; c4GL++; c4HL++;
			c4CR++; c4GR++; c4KR++; c4OR++;
			if (c4EL > d4E) c4EL = 0;
			if (c4FL > d4F) c4FL = 0;
			if (c4GL > d4G) c4GL = 0;
			if (c4HL > d4H) c4HL = 0;
