			hAL = a4EL[c4EL]; hBL = a4FL[c4FL]; hCL = a4GL[c4GL]; hDL = a4HL[c4HL];
			hAR = a4CR[c4CR]; hBR = a4GR[c4GR]; hCR = a4KR[c4KR]; hDR = a4OR[c4OR];
			hEL = -(hAL + hBL + hCL + hDL);
			hER = -(hAR + hBR + hCR + hDR);
			a4IL[c4IL] = hAL*2.0f + hEL;
